-- Run as the configured application schema user in Oracle 21c XE.
CREATE TABLE users (user_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, email VARCHAR2(254) NOT NULL UNIQUE, password_hash VARCHAR2(255) NOT NULL, display_name VARCHAR2(100) NOT NULL, created_at TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL);
CREATE TABLE categories (category_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id NUMBER NOT NULL REFERENCES users(user_id) ON DELETE CASCADE, name VARCHAR2(80) NOT NULL, category_type VARCHAR2(10) DEFAULT 'BOTH' NOT NULL CHECK(category_type IN ('INCOME','EXPENSE','BOTH')), is_essential CHAR(1) DEFAULT 'N' CHECK(is_essential IN ('Y','N')), CONSTRAINT uq_category_user UNIQUE(user_id,name), CONSTRAINT uq_category_owner_id UNIQUE(user_id,category_id));
CREATE TABLE transactions (transaction_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id NUMBER NOT NULL REFERENCES users(user_id) ON DELETE CASCADE, transaction_date DATE NOT NULL, amount NUMBER(14,2) NOT NULL CHECK(amount > 0), transaction_type VARCHAR2(10) NOT NULL CHECK(transaction_type IN ('INCOME','EXPENSE')), category_id NUMBER NOT NULL, description VARCHAR2(500), payment_method VARCHAR2(40), merchant_name VARCHAR2(120), import_hash VARCHAR2(64), created_at TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, CONSTRAINT fk_tx_owner_category FOREIGN KEY(user_id,category_id) REFERENCES categories(user_id,category_id));
CREATE UNIQUE INDEX uq_tx_import ON transactions(user_id,import_hash);
CREATE INDEX ix_tx_user_date ON transactions(user_id,transaction_date);
CREATE INDEX ix_tx_user_category ON transactions(user_id,category_id,transaction_date);
CREATE TABLE budgets (budget_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id NUMBER NOT NULL REFERENCES users(user_id) ON DELETE CASCADE, category_id NUMBER NOT NULL, month_start DATE NOT NULL, amount NUMBER(14,2) NOT NULL CHECK(amount>0), CONSTRAINT uq_budget UNIQUE(user_id,category_id,month_start), CONSTRAINT fk_budget_owner_category FOREIGN KEY(user_id,category_id) REFERENCES categories(user_id,category_id));
CREATE TABLE financial_goals (goal_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id NUMBER NOT NULL REFERENCES users(user_id) ON DELETE CASCADE, name VARCHAR2(120) NOT NULL, target_amount NUMBER(14,2) NOT NULL CHECK(target_amount>0), starting_amount NUMBER(14,2) DEFAULT 0 NOT NULL CHECK(starting_amount>=0), target_date DATE, status VARCHAR2(12) DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','COMPLETED','PAUSED')), created_at TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL);
CREATE TABLE goal_contributions (contribution_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, goal_id NUMBER NOT NULL REFERENCES financial_goals(goal_id) ON DELETE CASCADE, amount NUMBER(14,2) NOT NULL CHECK(amount>0), contribution_date DATE NOT NULL, note VARCHAR2(250));
CREATE TABLE anomaly_results (anomaly_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id NUMBER NOT NULL REFERENCES users(user_id) ON DELETE CASCADE, transaction_id NUMBER NOT NULL REFERENCES transactions(transaction_id) ON DELETE CASCADE, score NUMBER(12,8) NOT NULL, is_unusual CHAR(1) CHECK(is_unusual IN ('Y','N')), explanation VARCHAR2(1000), compared_amount NUMBER(14,2), analyzed_at TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL);
CREATE UNIQUE INDEX uq_anomaly_transaction ON anomaly_results(transaction_id);
CREATE TABLE spending_clusters (cluster_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id NUMBER NOT NULL REFERENCES users(user_id) ON DELETE CASCADE, month_start DATE NOT NULL, cluster_label NUMBER NOT NULL, description VARCHAR2(300) NOT NULL, profile_json CLOB CHECK(profile_json IS JSON), created_at TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, CONSTRAINT uq_cluster_month UNIQUE(user_id,month_start));
CREATE TABLE recommendations (recommendation_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id NUMBER NOT NULL REFERENCES users(user_id) ON DELETE CASCADE, title VARCHAR2(180) NOT NULL, explanation VARCHAR2(1000) NOT NULL, supporting_data CLOB CHECK(supporting_data IS JSON), comparison_period VARCHAR2(100), suggested_action VARCHAR2(500), priority VARCHAR2(10) CHECK(priority IN ('LOW','MEDIUM','HIGH')), created_at TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL);
CREATE TABLE simulation_results (simulation_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id NUMBER NOT NULL REFERENCES users(user_id) ON DELETE CASCADE, horizon_months NUMBER(3) NOT NULL CHECK(horizon_months BETWEEN 1 AND 60), simulations NUMBER(6) NOT NULL CHECK(simulations BETWEEN 100 AND 100000), scenario_inputs CLOB CHECK(scenario_inputs IS JSON), outputs CLOB CHECK(outputs IS JSON), created_at TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL);
